body.script:
//
// -----------------------------------------------------------------------------
// UTILITIES
// -----------------------------------------------------------------------------
const el = id => document.getElementById(id);
const show = id => { const e = el(id); if (e) { e.classList.remove('hidden'); e.style.display = ''; } };
const hide = id => { const e = el(id); if (e) { e.classList.add('hidden'); e.style.display = 'none'; } };
const toggleCls = (id, c, f) => { const e = el(id); if (e) e.classList.toggle(c, f); };
const setIn = (id, t) => { const e = el(id); if (e) e.innerText = t; };

// --- MODIFIKASI FITUR TEMA DIMULAI ---
const setH = (id, h) => { 
 const e = el(id); 
 if (e) {
 let tc = appData?.store?.themeColor || 'emerald';
 // Replace warna emerald ke warna tema pilihan secara otomatis saat render
 e.innerHTML = tc !== 'emerald' ? h.replace(/(bg-|text-|border-|ring-|from-|to-|shadow-|border-[tblr]-)emerald/g, '$1' + tc) : h;
 }
};

// Peta warna tema ke nilai hex & dark variant
const THEME_COLORS = {
 emerald: { p:'#059669', dark:'#047857', bg:'#ecfdf5', r:5, g:150, b:105 },
 teal: { p:'#0d9488', dark:'#0f766e', bg:'#f0fdfa', r:13, g:148, b:136 },
 blue: { p:'#2563eb', dark:'#1d4ed8', bg:'#eff6ff', r:37, g:99, b:235 },
 violet: { p:'#7c3aed', dark:'#6d28d9', bg:'#f5f3ff', r:124, g:58, b:237 },
 rose: { p:'#e11d48', dark:'#be123c', bg:'#fff1f2', r:225, g:29, b:72 },
 amber: { p:'#d97706', dark:'#b45309', bg:'#fffbeb', r:217, g:119, b:6 },
 orange: { p:'#ea580c', dark:'#c2410c', bg:'#fff7ed', r:234, g:88, b:12 },
 sky: { p:'#0284c7', dark:'#0369a1', bg:'#f0f9ff', r:2, g:132, b:199 },
 indigo: { p:'#4f46e5', dark:'#4338ca', bg:'#eef2ff', r:79, g:70, b:229 },
 pink: { p:'#db2777', dark:'#be185d', bg:'#fdf2f8', r:219, g:39, b:119 },
 cyan: { p:'#0891b2', dark:'#0e7490', bg:'#ecfeff', r:8, g:145, b:178 },
 lime: { p:'#65a30d', dark:'#4d7c0f', bg:'#f7fee7', r:101, g:163, b:13 },
};

// Update CSS variables & meta tag setiap kali tema berubah
window.updateThemeVars = () => {
 const tc = appData?.store?.themeColor || 'emerald';
 const t = THEME_COLORS[tc] || THEME_COLORS.emerald;
 const root = document.documentElement;
 root.style.setProperty('--clr-p', t.p);
 root.style.setProperty('--clr-p-dark', t.dark);
 root.style.setProperty('--clr-p-bg', t.bg);
 root.style.setProperty('--clr-p-10', `rgba(${t.r},${t.g},${t.b},0.10)`);
 root.style.setProperty('--clr-p-25', `rgba(${t.r},${t.g},${t.b},0.25)`);
 root.style.setProperty('--clr-p-35', `rgba(${t.r},${t.g},${t.b},0.35)`);
 // Sinkronkan meta theme-color untuk PWA toolbar
 const metaTheme = document.getElementById('pwa-theme-color');
 if (metaTheme) metaTheme.content = t.p;
};

window.applyGlobalTheme = () => {
 const tc = appData?.store?.themeColor || 'emerald';
 // Update CSS variables terlebih dahulu
 updateThemeVars();
 // Ganti class Tailwind emerald ke warna tema pilihan (untuk Tailwind JIT classes)
 if (tc !== 'emerald') {
 document.querySelectorAll('[class*="emerald"]').forEach(e => {
 e.className = e.className.replace(/(bg-|text-|border-|ring-|from-|to-|shadow-|border-[tblr]-)emerald/g, '$1' + tc);
 });
 }
};
// --- MODIFIKASI FITUR TEMA SELESAI ---

const setV = (id, v) => { const e = el(id); if (e) e.value = v; };
const getV = id => { const e = el(id); return e ? e.value : ''; };
const esc = s => !s ? '' : s.toString().replace(/[&<>'"]/g, t => ({ '&': '&', '<': '<', '>': '>', "'": '&#39;', '"': '&quot;' }[t]));

const fixD = v => {
 if (typeof v !== 'string') return v;
 const m = v.match(/drive\.google\.com.*(?:id=|\/d\/)([a-zA-Z0-9_-]+)/);
 // GANTI URL INI AGAR GAMBAR SELALU MUNCUL
 return m ? `https://lh3.googleusercontent.com/d/${m[1]}` : v;
};

// --- ENGINE LAZY LOADING GAMBAR ---
window.lazyObserver = new IntersectionObserver((entries, observer) => {
 entries.forEach(entry => {
 if (entry.isIntersecting) {
 const img = entry.target;
 if (img.dataset.src) {
 // Pindahkan URL asli dari data-src ke src
 img.src = img.dataset.src;
 // Saat gambar selesai diunduh, hilangkan opacity-0 untuk memicu efek Fade-In
 img.onload = () => img.classList.remove('opacity-0');
 // Hentikan pantauan pada gambar ini agar hemat RAM
 observer.unobserve(img);
 }
 }
 });
}, { rootMargin: "100px 0px" }); // Mulai muat saat gambar berjarak 100px sebelum masuk layar

window.observeLazyImages = () => {
 document.querySelectorAll('img.lazy-load').forEach(img => {
 window.lazyObserver.observe(img);
 });
};
// ----------------------------------

// -----------------------------------------------------------------------------
// CONFIGURATION & SETUP
// -----------------------------------------------------------------------------
const GAS_UPLOAD_URL = "https://script.google.com/macros/s/AKfycbw9LRofW_dHGiIOG3IlZ6sEs3YJRGk3z1X_AkAJLA1O7Hhzb_FE6VaL4AzjUrGRzI-w/exec";

// Gunakan konfigurasi Firebase terlengkap
const fbC = {
 apiKey: "AIzaSyCRp4LWBOJus2lcku8_5lHDmfakJfR5C2M",
 authDomain: "grafika24jam.firebaseapp.com",
 databaseURL: "https://grafika24jam-default-rtdb.asia-southeast1.firebasedatabase.app",
 projectId: "grafika24jam",
 storageBucket: "grafika24jam.firebasestorage.app",
 messagingSenderId: "109619354850",
 appId: "1:109619354850:web:171e508ae7d7d617e952bb",
 measurementId: "G-BDZ2NP8M96"
};

firebase.initializeApp(fbC);
const db = firebase.firestore(); 

// --- INI TAMBAHAN WAJIB UNTUK LOGIN EMAIL DEVELOPER ---
const auth = firebase.auth(); 
// -------------------------------------------------------

// [BUG 3 FIXED] Opsi 'merge' tidak valid di db.settings(). Hanya ignoreUndefinedProperties yang valid.
db.settings({ ignoreUndefinedProperties: true });

// Helper timeout untuk panggilan Firestore agar tidak hang jika offline / internet lambat
const withTimeout = (promise, timeoutMs = 3500) => {
 return Promise.race([
 promise,
 new Promise((_, reject) => setTimeout(() => reject(new Error("Firestore connection timeout")), timeoutMs))
 ]);
};

const defApp = {
 store: { 
 name: "TOKO GRAFIKA", slogan: "RITEL & GROSIR", logo: "fa-store", wa: "", address: "", lat: "", lng: "", costPerKm: 0, 
 isDeliveryEnabled: !0, isPickupEnabled: !0, allProductsIcon: "", categoryStyle: "text", footerText: "Terima kasih telah berbelanja di toko kami.",
 social: { fb: "", ig: "", tt: "", yt: "" }
 },
 auth: { username: "", password: "" },
 payment: { qrisUrl: "" },
 // --- TAMBAHAN UNTUK JASTIP ---
 jastip: {
 isActive: false,
 startHour: "08:00",
 endHour: "21:00",
 tarifPerKm: 10000,
 komisiDriver: 8000
 },
 drivers: [],
 // -----------------------------
 banks: [], banners: [], 
 categories: [
 { id: 1, name: "Makanan & Minuman", icon: "fa-utensils" },
 { id: 2, name: "Sembako", icon: "fa-basket-shopping" },
 { id: 3, name: "Kebutuhan Rumah", icon: "fa-house" }
 ], 
 vouchers: [], 
 products: [
 {
 id: 1,
 name: "Beras Premium Pulen 5kg",
 price: 68000,
 originalPrice: 75000,
 category: "Sembako",
 desc: "Beras pulen berkualitas super, bersih, tanpa pemutih dan pengawet.",
 stock: 25,
 img: "https://images.unsplash.com/pho e31c?w=500&auto=format&fit=crop&q=60",
 sku: "BRS-001",
 variants: [],
 wholesale: [{ min: 5, price: 65000 }]
 },
 {
 id: 2,
 name: "Minyak Goreng Pouch 2L",
 price: 34000,
 originalPrice: 38000,
 category: "Sembako",
 desc: "Minyak goreng kelapa sawit berkualitas jernih dan higienis.",
 stock: 40,
 img: "https://images.unsplash.com/pho eaacbcd87c5?w=500&auto=format&fit=crop&q=60",
 sku: "MYK-002",
 variants: []
 },
 {
 id: 3,
 name: "Kopi Arabika Nusantara 250g",
 price: 45000,
 originalPrice: 50000,
 category: "Makanan & Minuman",
 desc: "Biji kopi pilihan dengan aroma harum dan cita rasa nikmat khas nusantara.",
 stock: 15,
 img: "https://images.unsplash.com/pho a09d9b4aefdd?w=500&auto=format&fit=crop&q=60",
 sku: "KPI-003",
 variants: []
 }
 ], 
 licenseKey: "", promaxLicenseKey: "",
 accounts: [] 
};

let confirmCb = null;
let appData = JSON.parse(JSON.stringify(defApp));
let cart = [], wishlist = [];
let cust = { name: '', address: '', lat: null, lng: null, deliveryMethod: 'delivery', distance: 0, note: '' };
let vouch = null, aCat = 'Semua Produk', sQ = '', cSort = 'newest', cView = 'grid', cPage = 1, iPP = 12, cTab = 'orders', aSq = '';

// Tambahan: cRole & cPerms untuk RBAC
let eId = null, isAdm = !1, isPro = !1, isProMax = !1, cRole = 'admin', cPerms = [];
let cProd = null, cVar = 0, tVars = [], tWhol = [], cQty = 1;
let oMods = [], aOrdLst = null, gOrds = [], cVOrd = null;
let toastT, isSaving = !1;

window.verifyLicenseInDb = async (keyCode, expectedType) => {
 // 1. Cek apakah ada kode cadangan di brankas browser jika keyCode utama kosong
 const codeToCheck = keyCode || localStorage.getItem('freshmart_cache_' + expectedType);
 if (!codeToCheck) return false;

 try {
 // 2. Coba tanya ke server Firebase dengan timeout
 const doc = await withTimeout(db.collection("freshmart_licenses").doc(codeToCheck).get(), 3000);
 const isValid = doc.exists && doc.data().isActive === true && doc.data().type === expectedType;

 // 3. Jika valid, simpan ke brankas permanen browser sebagai cadangan
 if (isValid) {
 localStorage.setItem('freshmart_cache_' + expectedType, codeToCheck);
 } else {
 // Jika lisensi sengaja dimatikan (isActive: false) dari database, hapus dari brankas!
 localStorage.removeItem('freshmart_cache_' + expectedType);
 }
 return isValid;

 } catch (e) {
 console.warn("Gagal menghubungi server lisensi. Menggunakan cadangan lokal...", e);
 // 4. JIKA INTERNET MATI / LAMBAT: Jangan langsung salahkan pengguna.
 // Kita cek apakah mereka sebelumnya punya kode yang valid di brankas browser.
 const cachedCode = localStorage.getItem('freshmart_cache_' + expectedType);
 return (cachedCode === codeToCheck) && (cachedCode !== null); 
 }
};

// -----------------------------------------------------------------------------
// DATA MANAGEMENT
// -----------------------------------------------------------------------------
const sL = k => { try { return localStorage.getItem(k); } catch (e) { return null; } };

// Global handler: pastikan loader tidak stuck jika ada async crash tak terduga
window.addEventListener('unhandledrejection', e => {
 console.error('[FreshMart] Unhandled promise rejection:', e.reason);
 if (el('global-loader') && !el('global-loader').classList.contains('hidden')) {
 hLoad();
 showToast('Terjadi kesalahan. Silakan coba lagi.');
 }
});
const ssL = (k, v) => { try { localStorage.setItem(k, v); } catch (e) { if (e && (e.name === 'QuotaExceededError' || e.code === 22)) { console.warn('[FreshMart] localStorage penuh, cache lokal dilewati:', k); } } };

try { cart = JSON.parse(sL('freshmart_cart')) || []; } catch (e) { console.warn('[FreshMart] Cart parse error, reset:', e); }
try { wishlist = JSON.parse(sL('freshmart_wishlist')) || []; } catch (e) { console.warn('[FreshMart] Wishlist parse error, reset:', e); }

if (!history.state) history.replaceState({ view: 'view-catalog' }, '', '');

const sLoad = t => { if (t) setIn('loader-text', t); show('global-loader'); };
const hLoad = () => hide('global-loader');

const fCur = a => {
 const n = Number(a);
 return (isNaN(n) || a === null) ? 'Rp 0' : new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(Math.abs(n)).replace(/^/, n < 0 ? '-' : '');
};

window.getDist = (lat1, lon1, lat2, lon2) => {
 if (!lat1 || !lon1 || !lat2 || !lon2) return 0;
 const R = 6371; 
 const dLat = (lat2 - lat1) * Math.PI / 180;
 const dLon = (lon2 - lon1) * Math.PI / 180;
 const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
 const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
 return R * c; 
};

window.autoParseCoords = (input) => {
 const val = input.value.trim();
 const coords = val.split(',');
 if (coords.length >= 2) {
 const lat = parseFloat(coords[0].trim());
 const lng = parseFloat(coords[1].trim());
 if (!isNaN(lat) && !isNaN(lng)) {
 setV('set-lat', lat);
 setV('set-lng', lng);
 showToast("Koordinat tersalin!");
 return;
 }
 }
 showToast("Format salah! Coba: Lat, Lng");
};

window.handleImageUpload = async (inputElement, targetInputId, varIndex = null) => {
 const file = inputElement.files[0]; 
 if (!file) return;
 if (file.size > 3 * 1024 * 1024) { inputElement.value = ''; return showToast("Maksimal gambar 3MB!"); }
 if (!GAS_UPLOAD_URL || GAS_UPLOAD_URL.includes("ISI_DENGAN")) { inputElement.value = ''; return showToast("URL Google Apps Script belum diisi!"); }

 sLoad('Upload Gambar...'); 
 const reader = new FileReader(); 
 reader.readAsDataURL(file);

 reader.onload = async () => {
 try {
 const base64Data = reader.result.split(',')[1];
 const safeName = file.name.replace(/[^a-zA-Z0-9.]/g, '_');
 const payload = { name: "POS_" + Date.now() + "_" + safeName, mimeType: file.type, data: base64Data };

 const gasController = new AbortController();
 const gasTimeout = setTimeout(() => gasController.abort(), 30000);
 const res = await fetch(GAS_UPLOAD_URL, { method: 'POST', body: JSON.stringify(payload), headers: { 'Content-Type': 'text/plain;charset=utf-8' }, redirect: 'follow', signal: gasController.signal });
 clearTimeout(gasTimeout);
 const textRes = await res.text(); 
 let responseData;
 try { 
 responseData = JSON.parse(textRes); 
 } catch(e) { 
 hLoad(); inputElement.value = ''; 
 return showToast('Server GAS Error! Deploy ulang versi terbaru.'); 
 }
 if (responseData.status === 'success') {
 const finalUrl = fixD(responseData.url);
 const targetInput = el(targetInputId);
 if (targetInput) {
 targetInput.value = finalUrl; 
 targetInput.dispatchEvent(new Event('input', {bubbles:true})); 
 targetInput.dispatchEvent(new Event('change', {bubbles:true}));
 if (varIndex !== null) uVar(varIndex, 'img', finalUrl);
 showToast("Gambar berhasil diupload!");
 }
 } else {
 showToast("Gagal Drive: " + (responseData.message || "Unknown error"));
 }
 } catch (e) { 
 showToast("Koneksi terputus/CORS diblokir browser."); 
 }
 hLoad(); 
 inputElement.value = ''; 
 };
 reader.onerror = () => { showToast("Gagal membaca file!"); hLoad(); inputElement.value = ''; };
};

window.showToast = m => { 
 setIn('toast-message', m); 
 const t = el('toast'); 
 if (t) { 
 clearTimeout(toastT); 
 t.style.top = '20px'; 
 toastT = setTimeout(() => t.style.top = '-100px', 3000); 
 } 
};

// --- FUNGSI SALIN KODE VOUCHER ---
window.copyVoucher = (code) => {
 const copyProses = () => {
 const textArea = document.createElement("textarea");
 textArea.value = code;
 textArea.style.position = "fixed"; // Cegah layar meloncat ke bawah
 document.body.appendChild(textArea);
 textArea.focus();
 textArea.select();
 try {
 document.execCommand('copy');
 showToast(`Kode ${code} berhasil disalin! 🎉`);
 } catch (err) {
 showToast("Gagal menyalin kode.");
 }
 document.body.removeChild(textArea);
 };

 if (navigator.clipboard && window.isSecureContext) {
 navigator.clipboard.writeText(code).then(() => {
 showToast(`Kode ${code} berhasil disalin! 🎉`);
 }).catch(() => copyProses());
 } else {
 copyProses();
 }
};

window._cvBusy = false;
window.changeView = (v, fH = !1) => {
 if (!fH) history.pushState({ view: v }, '', '');
 const current = [...document.querySelectorAll('.view-section')].find(e => !e.classList.contains('hidden'));
 const target = el(v);
 if (!target || (current && current.id === v)) return;

 // Guard double-tap: jika sedang animasi, langsung skip ke target tanpa transisi
 if (window._cvBusy) {
 document.querySelectorAll('.view-section').forEach(e => {
 e.classList.add('hidden'); e.classList.remove('flex');
 e.style.opacity = ''; e.style.transform = ''; e.style.transition = '';
 });
 target.classList.remove('hidden'); target.classList.add('flex');
 const r2 = { 'view-cart': renderCart, 'view-checkout': rChck, 'view-payment': rPay, 'view-wishlist': renderWish };
 if (r2[v]) r2[v]();
 const s2 = target.querySelector('.scroll-content');
 if (s2) s2.scrollTo(0, 0);
 window._cvBusy = false;
 return;
 }

 // Jalankan render target dulu sebelum animasi mulai
 const r = { 'view-cart': renderCart, 'view-checkout': rChck, 'view-payment': rPay, 'view-wishlist': renderWish };
 if (r[v]) r[v]();
 const s = target.querySelector('.scroll-content');
 if (s) s.scrollTo(0, 0);

 if (!current) {
 document.querySelectorAll('.view-section').forEach(e => { e.classList.add('hidden'); e.classList.remove('flex'); });
 target.classList.remove('hidden');
 target.classList.add('flex');
 return;
 }

 window._cvBusy = true;

 // Fade out view lama
 current.style.transition = 'opacity 0.18s ease, transform 0.18s ease';
 current.style.opacity = '1';
 current.style.transform = 'translateY(0)';
 requestAnimationFrame(() => {
 current.style.opacity = '0';
 current.style.transform = 'translateY(6px)';
 });

 setTimeout(() => {
 document.querySelectorAll('.view-section').forEach(e => {
 e.classList.add('hidden');
 e.classList.remove('flex');
 e.style.opacity = '';
 e.style.transform = '';
 e.style.transition = '';
 });
 target.classList.remove('hidden');
 target.classList.add('flex');
 target.style.opacity = '0';
 target.style.transform = 'translateY(6px)';
 target.style.transition = 'opacity 0.18s ease, transform 0.18s ease';
 requestAnimationFrame(() => {
 requestAnimationFrame(() => {
 target.style.opacity = '1';
 target.style.transform = 'translateY(0)';
 });
 });
 // Bersihkan kolom pencarian saat kembali ke katalog
 if (v === 'view-catalog') {
 const si = el('search-input');
 if (si && si.value) { si.value = ''; sQ = ''; cPage = 1; rCat(); }
 const cb = el('btn-search-clear');
 if (cb) cb.classList.add('hidden');
 }
 setTimeout(() => {
 target.style.opacity = '';
 target.style.transform = '';
 target.style.transition = '';
 window._cvBusy = false;
 }, 200);
 }, 180);
};

window.toggleTheme = () => {
 const html = document.documentElement; 
 const icon = el('icon-theme');
 if (html.classList.contains('dark')) { 
 html.classList.remove('dark'); 
 localStorage.setItem('freshmart_theme', 'light'); 
 if (icon) icon.className = 'fa-solid fa-moon text-sm'; 
 } else { 
 html.classList.add('dark'); 
 localStorage.setItem('freshmart_theme', 'dark'); 
 if (icon) icon.className = 'fa-solid fa-sun text-sm text-amber-500'; 
 }
};

window.showConfirm = (t, m, cb, btnText = "Ya, Hapus", isDanger = true) => {
 setIn('confirm-title', t); 
 setIn('confirm-msg', m); 
 const b = el('confirm-yes-btn');
 if (b) {
 b.innerText = btnText;
 if (isDanger) {
 b.className = 'flex-1 py-3 bg-rose-600 text-white font-bold rounded-xl hover:bg-rose-700 transition-all text-sm shadow-md shadow-rose-500/20 border-2 border-rose-700';
 el('confirm-icon-box').className = 'w-14 h-14 bg-rose-50 dark:bg-rose-900/30 text-rose-500 dark:text-rose-400 rounded-2xl flex items-center justify-center text-2xl mx-auto mb-4 border-2 border-rose-100 dark:border-rose-800';
 el('confirm-icon').className = 'fa-solid fa-triangle-exclamation';
 } else {
 b.className = 'flex-1 py-3 bg-emerald-600 text-white font-bold rounded-xl hover:bg-emerald-700 transition-all text-sm shadow-md shadow-emerald-500/20 border-2 border-emerald-700';
 el('confirm-icon-box').className = 'w-14 h-14 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-500 dark:text-emerald-400 rounded-2xl flex items-center justify-center text-2xl mx-auto mb-4 border-2 border-emerald-100 dark:border-emerald-800';
 el('confirm-icon').className = 'fa-solid fa-copy';
 }
 }
 confirmCb = cb; 
 show('custom-confirm-modal'); 
 setTimeout(() => {
 el('custom-confirm-modal').classList.remove('opacity-0');
 el('custom-confirm-box').classList.remove('scale-95');
 }, 10);
};

window.closeConfirm = () => {
 el('custom-confirm-modal').classList.add('opacity-0');
 el('custom-confirm-box').classList.add('scale-95');
 setTimeout(() => hide('custom-confirm-modal'), 300);
};

window.executeConfirm = () => {
 if (confirmCb) confirmCb();
 closeConfirm();
};

// Inisialisasi CSS variables awal (emerald default) sebelum data dimuat
// agar tidak ada "flash" tampilan saat loadAppData masih async
(function initThemeEarly() {
 // Cek cache tema dari localStorage
 try {
 const cached = sessionStorage.getItem('freshmart_cms_data') || localStorage.getItem('freshmart_cms_data');
 if (cached) {
 const d = JSON.parse(cached);
 if (d.store && d.store.themeColor) {
 appData.store = appData.store || {};
 appData.store.themeColor = d.store.themeColor;
 }
 }
 } catch(e) { console.warn('[FreshMart] Gagal parse theme cache:', e); }
 const THEME_COLORS_EARLY = {
 emerald:'#059669,#047857,#ecfdf5,5,150,105',
 teal:'#0d9488,#0f766e,#f0fdfa,13,148,136',
 blue:'#2563eb,#1d4ed8,#eff6ff,37,99,235',
 violet:'#7c3aed,#6d28d9,#f5f3ff,124,58,237',
 rose:'#e11d48,#be123c,#fff1f2,225,29,72',
 amber:'#d97706,#b45309,#fffbeb,217,119,6',
 orange:'#ea580c,#c2410c,#fff7ed,234,88,12',
 sky:'#0284c7,#0369a1,#f0f9ff,2,132,199',
 indigo:'#4f46e5,#4338ca,#eef2ff,79,70,229',
 pink:'#db2777,#be185d,#fdf2f8,219,39,119',
 cyan:'#0891b2,#0e7490,#ecfeff,8,145,178',
 lime:'#65a30d,#4d7c0f,#f7fee7,101,163,13',
 };
 const tc = (appData.store && appData.store.themeColor) || 'emerald';
 const v = (THEME_COLORS_EARLY[tc] || THEME_COLORS_EARLY.emerald).split(',');
 const r = document.documentElement;
 r.style.setProperty('--clr-p', v[0]);
 r.style.setProperty('--clr-p-dark', v[1]);
 r.style.setProperty('--clr-p-bg', v[2]);
 r.style.setProperty('--clr-p-10', `rgba(${v[3]},${v[4]},${v[5]},0.10)`);
 r.style.setProperty('--clr-p-25', `rgba(${v[3]},${v[4]},${v[5]},0.25)`);
 r.style.setProperty('--clr-p-35', `rgba(${v[3]},${v[4]},${v[5]},0.35)`);
})();

const loadAppData = async () => {
 console.log('[FreshMart] 1. loadAppData started');
 if (document.documentElement.classList.contains('dark')) { 
 const icon = el('icon-theme'); 
 if (icon) icon.className = 'fa-solid fa-sun text-sm text-amber-500'; 
 }
 sLoad('Sinkron Data...');
 try {
 console.log('[FreshMart] 2. Fetching cms_data from Firestore...');
 const d = await withTimeout(db.collection("freshmart").doc("cms_data").get(), 3000);
 let localProducts = JSON.parse(sL('freshmart_products') || 'null');
 let localUpdate = parseInt(sL('freshmart_last_update') || '0');

 if (d.exists) {
 console.log('[FreshMart] 2a. cms_data document exists');
 const f = d.data(); 
 let oldLic = appData.licenseKey; 
 let oldProMaxLic = appData.promaxLicenseKey;
 appData = { ...defApp, ...f }; 
 appData.licenseKey = f.licenseKey || oldLic || ""; 
 appData.promaxLicenseKey = f.promaxLicenseKey || oldProMaxLic || "";

 appData.store = { ...defApp.store, ...(f.store || {}) }; 
 if(!appData.store.social) appData.store.social = defApp.store.social;
 appData.auth = { ...defApp.auth, ...(f.auth || {}) }; 
 appData.payment = { ...defApp.payment, ...(f.payment || {}) };
 const serverUpdate = f.lastUpdate || 0;

 if (f.products && f.products.length > 0) {
 const batch = db.batch(); 
 f.products.forEach(p => { batch.set(db.collection("freshmart").doc("cms_data").collection("products").doc(p.id.toString()), p); });
 await batch.commit(); 
 await db.collection("freshmart").doc("cms_data").update({ products: firebase.firestore.FieldValue.delete(), lastUpdate: Date.now() });
 appData.products = f.products.sort((a, b) => (b.id || 0) - (a.id || 0)); 
 ssL('freshmart_products', JSON.stringify(appData.products));
 } else {
 if (localProducts && localUpdate >= serverUpdate) {
 appData.products = localProducts;
 } else { 
 const pSnap = await withTimeout(db.collection("freshmart").doc("cms_data").collection("products").get(), 3000); 
 appData.products = pSnap.docs.map(doc => doc.data()).sort((a, b) => (b.id || 0) - (a.id || 0)); 
 ssL('freshmart_products', JSON.stringify(appData.products)); 
 ssL('freshmart_last_update', serverUpdate.toString()); 
 }
 }
 } else {
 console.log('[FreshMart] 2b. cms_data does not exist, using default data');
 }
 } catch (e) {
 console.warn('[FreshMart] 2c. Firestore offline or failed:', e.message); 
 const l = JSON.parse(sL('freshmart_cms_data') || 'null'); 
 const lp = JSON.parse(sL('freshmart_products') || 'null');
 if (l) { 
 appData = { ...defApp, ...l }; 
 appData.store = { ...defApp.store, ...(l.store || {}) };
 if(!appData.store.social) appData.store.social = defApp.store.social;
 }
 if (lp) { appData.products = lp; } 
 showToast("Mode Offline (Data Lokal)");
 } finally {
 // ============================================================
 // CRITICAL: Seluruh rendering & hLoad() ada di finally block
 // agar loading overlay SELALU hilang, bahkan jika ada error.
 // ============================================================
 try {
 appData.products = appData.products || []; 
 appData.categories = appData.categories || [];
 appData.accounts = appData.accounts || []; 

 appData.products.forEach(p => { 
 if(p.img) p.img = fixD(p.img); 
 if (p.variants) p.variants.forEach(v => { if(v.img) v.img = fixD(v.img); }); 
 });

 if (appData.banners) appData.banners.forEach(b => { if(b.img) b.img = fixD(b.img); }); 
 if (appData.categories) appData.categories.forEach(c => { if(c.img) c.img = fixD(c.img); });

 if(appData.store.logo) appData.store.logo = fixD(appData.store.logo); 
 if(appData.store.allProductsIcon) appData.store.allProductsIcon = fixD(appData.store.allProductsIcon); 
 if(appData.payment.qrisUrl) appData.payment.qrisUrl = fixD(appData.payment.qrisUrl);

 cart.forEach(i => { if(i.img) i.img = fixD(i.img); }); 
 wishlist.forEach(i => { if(i.img) i.img = fixD(i.img); });

 console.log('[FreshMart] 3. Rendering catalog & themes...');
        updWish();
        updCart();
        const _siInit = el('search-input');
        if (_siInit) _siInit.value = '';
        sQ = '';
        rDyn();
        applyGlobalTheme();

 console.log('[FreshMart] 4. Verifying license keys...');
 try {
 let savedProKey = (appData.licenseKey || localStorage.getItem('freshmart_cache_PRO') || '').trim().toUpperCase();
 let savedProMaxKey = (appData.promaxLicenseKey || localStorage.getItem('freshmart_cache_PROMAX') || '').trim().toUpperCase();

 isPro = await verifyLicenseInDb(savedProKey, 'PRO');
 isProMax = await verifyLicenseInDb(savedProMaxKey, 'PROMAX');

 if (isPro) appData.licenseKey = savedProKey;
 if (isProMax) appData.promaxLicenseKey = savedProMaxKey;
 } catch (licErr) {
 console.warn("[FreshMart] Gagal verifikasi lisensi saat startup:", licErr);
 isPro = !!localStorage.getItem('freshmart_cache_PRO');
 isProMax = !!localStorage.getItem('freshmart_cache_PROMAX');
 }

 const pid = new URLSearchParams(window.location.search).get('p'); 
 if (pid && appData.products.find(x => x.id == parseInt(pid))) {
 setTimeout(() => openProductModal(parseInt(pid)), 600);
 }

 buildAndInjectManifest();
 startPriceWatcher();
 } catch (renderErr) {
 console.error('[FreshMart] Render error in finally block:', renderErr);
 } finally {
 // ABSOLUTE GUARANTEE: loader selalu hilang
 hLoad();
 console.log('[FreshMart] 6. App initialization complete!');
 }
 }
};

const saveApp = async () => { 
 try { 
 appData.lastUpdate = Date.now(); 
 const copyData = { ...appData }; 
 delete copyData.products; 
 await db.collection("freshmart").doc("cms_data").set(copyData); 
 ssL('freshmart_cms_data', JSON.stringify(copyData)); 
 ssL('freshmart_last_update', appData.lastUpdate.toString()); 
 ssL('freshmart_products', JSON.stringify(appData.products)); 
 } catch (e) { 
 showToast("Tersimpan Lokal"); 
 } 
};

window.checkAdminAccess = () => isAdm ? (changeView('view-admin'), openAdminMenu()) : (setV('login-username', ''), setV('login-password', ''), changeView('view-admin-login'));

window.getEffP = i => {
 const p = appData.products.find(x => x.id === i.id);
 if (!p || !p.wholesale || !p.wholesale.length) return i.price;
 const t = cart.filter(c => c.id === i.id).reduce((s, c) => s + c.qty, 0);
 for (let w of p.wholesale.slice().sort((a, b) => b.minQty - a.minQty)) {
 if (t >= w.minQty) return w.price;
 }
 return i.price;
};

