 sLoad('Memverifikasi Lisensi...');
 const isValid = await verifyLicenseInDb(c, 'PRO');

 if (isValid) {
 appData.licenseKey = c; 
 localStorage.setItem('freshmart_cache_PRO', c); // SIMPAN KE BRANKAS PERMANEN
 isPro = !0;
 setH('admin-pro-badge', '<span class="badge badge-xs badge-solid-amber"><i class="fa-solid fa-crown"></i> PRO</span>');
 await saveApp(); 
 showToast("Akses PRO Terbuka!"); 
 openAdminTab(cTab);
 } else {
 showToast("Kode Lisensi Tidak Valid / Nonaktif!");
 }
 hLoad();
};

window.activateProMax = async () => {
 if (isSaving) return;
 const c = getV('promax-license-input').trim().toUpperCase();

 sLoad('Memverifikasi Langganan...');
 const isValid = await verifyLicenseInDb(c, 'PROMAX');

 if (isValid) {
 appData.promaxLicenseKey = c; 
 localStorage.setItem('freshmart_cache_PROMAX', c); // SIMPAN KE BRANKAS PERMANEN
 isProMax = !0;
 try {
 await saveApp();
 showToast("Berhasil! Fitur PRO MAX Terbuka."); 
 openAdminTab('promax'); 
 } catch (e) {
 showToast("Gagal menyimpan lisensi ke server.");
 }
 } else {
 showToast("Kode Langganan Tidak Valid / Kedaluwarsa!");
 }
 hLoad();
};

