// ============================================================
// FITUR PWA — Install di Android, iOS, dan Desktop
// ============================================================

let _pwaInstallEvent = null; // Simpan event beforeinstallprompt

// 1. Tangkap event install dari browser (Chrome Android & Desktop)
window.addEventListener('beforeinstallprompt', e => {
 e.preventDefault();
 _pwaInstallEvent = e;
 // Tampilkan banner hanya jika belum pernah di-dismiss
 if (!sessionStorage.getItem('pwa_banner_dismissed')) {
 setTimeout(showPwaBanner, 2500); // Tunda 2.5 detik agar tidak mengganggu loading
 }
});

// 2. Deteksi apakah sudah berjalan sebagai PWA (standalone)
const isPwaInstalled = () =>
 window.matchMedia('(display-mode: standalone)').matches ||
 window.navigator.standalone === true ||
 document.referrer.includes('android-app://');

// 3. Bangun manifest.json secara dinamis dari data toko
// ============================================================
// RENDER LOGO TOKO KE PNG (untuk ikon PWA & splash screen)
// Mendukung: URL gambar (http/data:) DAN FontAwesome class
// ============================================================
const _pwaIconCache = {};

const _darkenHex = (hex, pct) => {
 const num = parseInt(hex.replace('#',''), 16);
 const r = Math.max(0, (num >> 16) - Math.round(255 * pct));
 const g = Math.max(0, ((num >> 8) & 0xff) - Math.round(255 * pct));
 const b = Math.max(0, (num & 0xff) - Math.round(255 * pct));
 return '#' + ((1<<24)|(r<<16)|(g<<8)|b).toString(16).slice(1);
};

const _drawTextFallback = (ctx, size, storeName) => {
 const initials = (storeName || 'T').split(' ').map(w => w[0]).join('').toUpperCase().substring(0, 2);
 const fontSize = size * 0.38;
 ctx.font = '900 ' + fontSize + 'px "Plus Jakarta Sans", sans-serif';
 ctx.fillStyle = 'rgba(255,255,255,0.95)';
 ctx.textAlign = 'center';
 ctx.textBaseline = 'middle';
 ctx.fillText(initials, size / 2, size / 2);
};

const renderLogoToCanvas = async (logo, themeHex, storeName, size) => {
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');

    // Latar solid warna tema
    ctx.fillStyle = themeHex;
    ctx.fillRect(0, 0, size, size);

    const isImageUrl = logo && (logo.startsWith('http') || logo.startsWith('https') || logo.startsWith('data:'));
    const isFaIcon = logo && !isImageUrl && logo.trim().length > 0;
    const pad = size * 0.12;

    if (isImageUrl) {
        try {
            const img = await _loadImgOnce(logo);
            const draw = size - pad * 2;
            let dw = draw, dh = draw;
            if (img.width > img.height) dh = draw * (img.height / img.width);
            else if (img.height > img.width) dw = draw * (img.width / img.height);
            ctx.drawImage(img, (size-dw)/2, (size-dh)/2, dw, dh);
            return canvas.toDataURL('image/png');
        } catch (e) {
            _drawTextFallback(ctx, size, storeName);
            return canvas.toDataURL('image/png');
        }
    } else if (isFaIcon) {
        const faMap = {
            'fa-store':'\uf54e','fa-shop':'\uf54f','fa-shopping-cart':'\uf07a','fa-shopping-bag':'\uf290',
            'fa-basket-shopping':'\uf291','fa-cart-shopping':'\uf07a','fa-tag':'\uf02b','fa-tags':'\uf02c',
            'fa-box':'\uf466','fa-box-open':'\uf49e','fa-boxes-stacked':'\uf468','fa-building':'\uf1ad',
            'fa-house':'\uf015','fa-home':'\uf015','fa-utensils':'\uf2e7','fa-burger':'\uf805',
            'fa-pizza-slice':'\uf818','fa-leaf':'\uf06c','fa-seedling':'\uf4d8','fa-tree':'\uf1bb',
            'fa-star':'\uf005','fa-heart':'\uf004','fa-gem':'\uf3a5','fa-crown':'\uf521',
            'fa-bolt':'\uf0e7','fa-fire':'\uf06d','fa-truck':'\uf0d1','fa-motorcycle':'\uf21c',
            'fa-bicycle':'\uf206','fa-tshirt':'\uf553','fa-shirt':'\uf553','fa-glasses':'\uf530',
            'fa-mobile':'\uf10b','fa-laptop':'\uf109','fa-camera':'\uf030','fa-music':'\uf001',
            'fa-book':'\uf02d','fa-gamepad':'\uf11b','fa-paw':'\uf1b0','fa-fish':'\uf578',
            'fa-apple-whole':'\uf5d1','fa-carrot':'\uf787','fa-bread-slice':'\uf7ec',
            'fa-coffee':'\uf0f4','fa-mug-hot':'\uf7b6','fa-wine-glass':'\uf4e3',
            'fa-pills':'\uf484','fa-spa':'\uf5bb','fa-scissors':'\uf0c4',
            'fa-wrench':'\uf0ad','fa-hammer':'\uf6e3','fa-paint-roller':'\uf5aa',
            'fa-palette':'\uf53f','fa-pen':'\uf304','fa-pencil':'\uf303'
        };
        const cleanClass = logo.replace(/^fa-(solid|regular|brands|light|thin|duotone)\s+/, '').trim();
        const unicode = faMap[cleanClass] || null;
        const iconSize = size * 0.52;
        return new Promise(resolve => {
            const tryRender = () => {
                ctx.font = '900 ' + iconSize + 'px "Font Awesome 6 Free"';
                ctx.fillStyle = 'rgba(255,255,255,0.95)';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(unicode || '\uf54e', size/2, size/2 + iconSize*0.04);
                resolve(canvas.toDataURL('image/png'));
            };
            if (document.fonts && document.fonts.ready) document.fonts.ready.then(tryRender);
            else setTimeout(tryRender, 500);
        });
    } else {
        _drawTextFallback(ctx, size, storeName);
        return canvas.toDataURL('image/png');
    }
};

// ============================================================
// SPLASH SCREEN iOS — render canvas full-screen per device
// ============================================================
const _injectIosSplashScreen = async (logo, themeHex, storeName) => {
    const isIos = /iphone|ipad|ipod/i.test(navigator.userAgent);
    if (!isIos) return; // Hanya jalankan di perangkat iOS untuk hemat request

    document.querySelectorAll('link[rel="apple-touch-startup-image"]').forEach(el => el.remove());
    const splashSizes = [
        { w:1125, h:2436, media:'(device-width:375px) and (device-height:812px) and (-webkit-device-pixel-ratio:3)' },
        { w:1170, h:2532, media:'(device-width:390px) and (device-height:844px) and (-webkit-device-pixel-ratio:3)' },
        { w:1290, h:2796, media:'(device-width:430px) and (device-height:932px) and (-webkit-device-pixel-ratio:3)' },
        { w:828,  h:1792, media:'(device-width:414px) and (device-height:896px) and (-webkit-device-pixel-ratio:2)' },
        { w:750,  h:1334, media:'(device-width:375px) and (device-height:667px) and (-webkit-device-pixel-ratio:2)' },
        { w:1536, h:2048, media:'(device-width:768px) and (device-height:1024px) and (-webkit-device-pixel-ratio:2)' },
        { w:2048, h:2732, media:'(device-width:1024px) and (device-height:1366px) and (-webkit-device-pixel-ratio:2)' }
    ];
    const renderSplash = async (w, h) => {
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = themeHex;
        ctx.fillRect(0, 0, w, h);
        const logoSize = Math.round(w * 0.24);
        const logoX = (w - logoSize) / 2;
        const logoY = (h - logoSize) / 2 - h * 0.05;
        // Lingkaran latar logo
        ctx.save();
        ctx.beginPath();
        ctx.arc(w/2, logoY + logoSize/2, logoSize * 0.68, 0, Math.PI*2);
        ctx.fillStyle = 'rgba(255,255,255,0.15)';
        ctx.fill();
        ctx.restore();
        // Gambar logo di tengah splash
        const isImgUrl = logo && (logo.startsWith('http') || logo.startsWith('https') || logo.startsWith('data:'));
        if (isImgUrl) {
            try {
                const img = await _loadImgOnce(logo);
                let dw=logoSize, dh=logoSize;
                if (img.width>img.height) dh=logoSize*(img.height/img.width);
                else if (img.height>img.width) dw=logoSize*(img.width/img.height);
                ctx.drawImage(img, logoX+(logoSize-dw)/2, logoY+(logoSize-dh)/2, dw, dh);
            } catch (e) {
                ctx.save(); ctx.translate(logoX,logoY); _drawTextFallback(ctx,logoSize,storeName); ctx.restore();
            }
        } else {
            ctx.save();
            ctx.translate(logoX, logoY);
            _drawTextFallback(ctx, logoSize, storeName);
            ctx.restore();
        }
        // Nama toko
        const nameFz = Math.round(w * 0.052);
        ctx.font = '700 ' + nameFz + 'px "Plus Jakarta Sans", sans-serif';
        ctx.fillStyle = '#ffffff';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText(storeName, w/2, logoY + logoSize + h*0.032);
        return canvas.toDataURL('image/png');
    };
    for (const s of splashSizes) {
        try {
            const dataUrl = await renderSplash(s.w, s.h);
            const linkEl = document.createElement('link');
            linkEl.rel = 'apple-touch-startup-image';
            linkEl.href = dataUrl;
            linkEl.media = s.media;
            document.head.appendChild(linkEl);
        } catch(e) { /* skip ukuran yang gagal */ }
    }
};

// ============================================================
// BUILD & INJECT MANIFEST — Semua dari logo toko
// ============================================================
const buildAndInjectManifest = async () => {
 const storeName = appData?.store?.name || 'Toko';
 const storeSlogan = appData?.store?.slogan || '';
 const logo = appData?.store?.logo || '';
 const tc = appData?.store?.themeColor || 'emerald';
 const colorMap = {
 emerald:'#059669', teal:'#0d9488', blue:'#2563eb', violet:'#7c3aed',
 rose:'#e11d48', amber:'#d97706', orange:'#ea580c', sky:'#0284c7',
 indigo:'#4f46e5', pink:'#db2777', cyan:'#0891b2', lime:'#65a30d'
 };
 const themeHex = colorMap[tc] || '#059669';

 // Update meta tags
 const metaTheme = document.getElementById('pwa-theme-color');
 if (metaTheme) metaTheme.content = themeHex;
 const metaIosTitle = document.getElementById('pwa-app-name-ios');
 if (metaIosTitle) metaIosTitle.content = storeName;

 // Cache key agar tidak render ulang jika logo & warna sama
 const cacheKey = logo + '|' + themeHex + '|' + storeName;
 let icon192, icon512, icon180;
 if (_pwaIconCache[cacheKey]) {
 ({ icon192, icon512, icon180 } = _pwaIconCache[cacheKey]);
 } else {
 [icon192, icon512, icon180] = await Promise.all([
 renderLogoToCanvas(logo, themeHex, storeName, 192),
 renderLogoToCanvas(logo, themeHex, storeName, 512),
 renderLogoToCanvas(logo, themeHex, storeName, 180)
 ]);
 _pwaIconCache[cacheKey] = { icon192, icon512, icon180 };
 }

 // Update semua apple-touch-icon (iOS home screen icon)
 ['pwa-apple-touch-icon','pwa-apple-touch-icon-76','pwa-apple-touch-icon-120',
 'pwa-apple-touch-icon-152','pwa-apple-touch-icon-180'].forEach(id => {
 const el2 = document.getElementById(id);
 if (el2) el2.href = icon180;
 });

 // Inject splash screen iOS
 _injectIosSplashScreen(logo, themeHex, storeName);

 // Icon langsung pakai data URL (base64) — skema 'blob:' tidak didukung sebagai icon src di manifest
 const url192 = icon192, url512 = icon512;

 // Manifest JSON lengkap
 const manifest = {
 name: storeName,
 short_name: storeName.length > 12 ? storeName.substring(0,12) : storeName,
 description: storeSlogan || ('Belanja di ' + storeName),
 start_url: window.location.href.split('?')[0],
 scope: window.location.href.split('?')[0],
 display: 'standalone',
 orientation: 'portrait-primary',
 background_color: themeHex,
 theme_color: themeHex,
 icons: [
 { src: url192, sizes: '192x192', type: 'image/png', purpose: 'any' },
 { src: url192, sizes: '192x192', type: 'image/png', purpose: 'maskable' },
 { src: url512, sizes: '512x512', type: 'image/png', purpose: 'any' },
 { src: url512, sizes: '512x512', type: 'image/png', purpose: 'maskable' }
 ],
 categories: ['shopping','business'],
 lang: 'id'
 };

 const manifestBlob = new Blob([JSON.stringify(manifest)], { type: 'application/json' });
 const manifestUrl = URL.createObjectURL(manifestBlob);
 const link = document.getElementById('pwa-manifest-link');
 if (link) {
 if (link.href && link.href.startsWith('blob:')) URL.revokeObjectURL(link.href);
 link.href = manifestUrl;
 }
};

// 4. Tampilkan banner install
window.showPwaBanner = () => {
 if (isPwaInstalled()) return; // Jangan tampilkan jika sudah diinstall
 const banner = document.getElementById('pwa-install-banner');
 if (!banner) return;

 const isIos = /iphone|ipad|ipod/i.test(navigator.userAgent);
 const isDesktop = !('ontouchstart' in window) && !/android/i.test(navigator.userAgent) && !isIos;
 const isSafari = /^((?!chrome|android).)*safari/i.test(navigator.userAgent);

 // Sesuaikan teks & ikon berdasarkan platform
 if (isIos && isSafari) {
 // iOS Safari: tidak ada beforeinstallprompt, tampilkan petunjuk manual
 setIn('pwa-banner-title', 'Tambah ke Layar Utama (iOS)');
 setIn('pwa-banner-desc', 'Ketuk ikon Bagikan → "Add to Home Screen"');
 const icon = document.getElementById('pwa-banner-icon');
 if (icon) icon.className = 'fa-solid fa-arrow-up- text-white text-xl';
 const btn = document.getElementById('pwa-install-btn');
 if (btn) { btn.textContent = 'Cara Install'; btn.onclick = showIosInstallGuide; }
 } else if (isDesktop) {
 setIn('pwa-banner-title', 'Install Aplikasi di PC / Laptop');
 setIn('pwa-banner-desc', 'Buka lebih cepat tanpa browser, seperti aplikasi desktop');
 const icon = document.getElementById('pwa-banner-icon');
 if (icon) icon.className = 'fa-solid fa-desktop text-white text-xl';
 } else {
 // Android
 setIn('pwa-banner-title', 'Tambahkan ke Layar Utama');
 setIn('pwa-banner-desc', 'Install aplikasi toko ini di HP Anda');
 }

 banner.classList.remove('hidden');
};

// 5. Trigger install (Android & Desktop)
window.triggerPwaInstall = async () => {
 if (_pwaInstallEvent) {
 _pwaInstallEvent.prompt();
 const { outcome } = await _pwaInstallEvent.userChoice;
 if (outcome === 'accepted') {
 showToast('Aplikasi berhasil diinstall! 🎉');
 dismissPwaBanner();
 }
 _pwaInstallEvent = null;
 } else {
 // Fallback: tidak ada event (mungkin sudah installed atau browser lama)
 showToast('Gunakan menu browser → "Tambah ke Layar Utama"');
 }
};

// 6. Dismiss banner (simpan ke session agar tidak muncul lagi dalam sesi ini)
window.dismissPwaBanner = () => {
 const banner = document.getElementById('pwa-install-banner');
 if (banner) {
 banner.style.transition = 'all 0.3s ease';
 banner.style.opacity = '0';
 banner.style.transform = 'translateY(-8px)';
 setTimeout(() => banner.classList.add('hidden'), 300);
 }
 sessionStorage.setItem('pwa_banner_dismissed', '1');
};

// 7. Panduan khusus iOS (modal toast bertahap)
window.showIosInstallGuide = () => {
 showConfirm(
 '📱 Cara Install di iPhone / iPad',
 '1. Ketuk ikon Bagikan (kotak + panah atas) di toolbar Safari\n2. Gulir ke bawah, pilih "Add to Home Screen"\n3. Ketuk "Add" di pojok kanan atas\n\nAplikasi akan muncul di layar utama Anda!',
 () => {},
 'Mengerti',
 false
 );
};

// 8. Event: browser memberi tahu install selesai
window.addEventListener('appinstalled', () => {
 showToast('Berhasil diinstall di layar utama! 🎉');
 dismissPwaBanner();
 _pwaInstallEvent = null;
});

// 9. Jangan tampilkan banner jika sudah berjalan sebagai PWA
if (isPwaInstalled()) {
 sessionStorage.setItem('pwa_banner_dismissed', '1');
}

// ============================================================
// SINKRONISASI HARGA REAL-TIME — Keranjang & Favorit
// ============================================================
// Saat admin mengupdate harga produk, harga di cart & wishlist
// otomatis ikut berubah tanpa harus reload halaman.

// Fungsi inti: sinkronkan harga satu produk ke cart & wishlist
const syncProductPrice = (updatedProduct) => {
 if (!updatedProduct || !updatedProduct.id) return;

 let cartChanged = false;
 let wishlistChanged = false;

 // --- Sinkronisasi KERANJANG ---
 cart.forEach(item => {
 if (item.id !== updatedProduct.id) return;

 // Sync unit jika berubah
 if (item.unit !== (updatedProduct.unit || '')) {
 item.unit = updatedProduct.unit || '';
 cartChanged = true;
 }

 // Harga dasar (tanpa varian)
 const newBasePrice = updatedProduct.price;

 // Harga varian (jika ada)
 let newVariantPrice = newBasePrice;
 if (item.variantName && updatedProduct.variants && updatedProduct.variants.length > 0) {
 const matchedVariant = updatedProduct.variants.find(v => v.name === item.variantName);
 if (matchedVariant) newVariantPrice = matchedVariant.price;
 }

 const oldPrice = item.price;
 item.price = newVariantPrice;

 // Update juga gambar jika berubah
 if (item.variantName && updatedProduct.variants) {
 const mv = updatedProduct.variants.find(v => v.name === item.variantName);
 if (mv && mv.img) item.img = fixD(mv.img);
 } else if (updatedProduct.img) {
 item.img = fixD(updatedProduct.img);
 }

 if (oldPrice !== item.price) cartChanged = true;
 });

 // --- Sinkronisasi FAVORIT (WISHLIST) ---
 wishlist.forEach(item => {
 if (item.id !== updatedProduct.id) return;

 // Sync unit jika berubah
 if (item.unit !== (updatedProduct.unit || '')) {
 item.unit = updatedProduct.unit || '';
 wishlistChanged = true;
 }

 const newBasePrice = updatedProduct.price;
 let newVariantPrice = newBasePrice;
 if (item.variantName && updatedProduct.variants && updatedProduct.variants.length > 0) {
 const matchedVariant = updatedProduct.variants.find(v => v.name === item.variantName);
 if (matchedVariant) newVariantPrice = matchedVariant.price;
 }

 const oldPrice = item.price;
 item.price = newVariantPrice;

 if (item.variantName && updatedProduct.variants) {
 const mv = updatedProduct.variants.find(v => v.name === item.variantName);
 if (mv && mv.img) item.img = fixD(mv.img);
 } else if (updatedProduct.img) {
 item.img = fixD(updatedProduct.img);
 }

 if (oldPrice !== item.price) wishlistChanged = true;
 });

 // Jika ada perubahan harga, simpan & re-render
 if (cartChanged) {
 ssL('freshmart_cart', JSON.stringify(cart));
 updCart();
 // Jika sedang di halaman keranjang, render ulang
 const cartView = document.getElementById('view-cart');
 if (cartView && cartView.classList.contains('flex')) renderCart();
 // Jika sedang di halaman pembayaran, render ulang
 const payView = document.getElementById('view-payment');
 if (payView && payView.classList.contains('flex')) rPay();
 }

 if (wishlistChanged) {
 ssL('freshmart_wishlist', JSON.stringify(wishlist));
 updWish();
 const wishView = document.getElementById('view-wishlist');
 if (wishView && wishView.classList.contains('flex')) renderWish();
 }

 // Jika modal produk sedang terbuka untuk produk ini, refresh tampilannya
 if (cProd && cProd.id === updatedProduct.id) {
 cProd = updatedProduct; // update referensi produk
 rProdMod();
 }

 if (cartChanged || wishlistChanged) {
 showToast('💰 Harga produk telah diperbarui!');
 }
};

// Listener Firestore real-time untuk koleksi produk
// Berjalan di background — otomatis mendeteksi perubahan harga dari admin
let _priceWatcherUnsub = null;
let _priceWatcherLegacyUnsub = null;
let _priceDebounceTimer = null;

// Debounce sinkronisasi harga agar tidak spam re-render
// jika banyak produk diupdate sekaligus
const _debouncedSync = (updatedProduct) => {
 clearTimeout(_priceDebounceTimer);
 _priceDebounceTimer = setTimeout(() => syncProductPrice(updatedProduct), 120);
};

window.startPriceWatcher = () => {
 // --- LISTENER 1: Subcollection products (toko yang sudah migrasi) ---
 if (!_priceWatcherUnsub) {
 _priceWatcherUnsub = db.collection('freshmart')
 .doc('cms_data')
 .collection('products')
 .onSnapshot(snapshot => {
 let isFirstLoad = true;
 snapshot.docChanges().forEach(change => {
 // Skip perubahan awal saat listener pertama terhubung
 if (change.type === 'modified') {
 const updatedProduct = change.doc.data();
 const idx = appData.products.findIndex(p => p.id == updatedProduct.id);
 if (idx > -1) {
 appData.products[idx] = { ...appData.products[idx], ...updatedProduct };
 }
 _debouncedSync(updatedProduct);
 }
 });
 }, err => {
 console.warn('[PriceWatcher] Subcollection error, retry in 10s:', err);
 _priceWatcherUnsub = null;
 setTimeout(() => { if (!_priceWatcherUnsub) startPriceWatcher(); }, 10000);
 });
 }

 // --- LISTENER 2: cms_data document (toko yang masih simpan produk di sini) ---
 if (!_priceWatcherLegacyUnsub) {
 let _legacyPrevProducts = null;
 _priceWatcherLegacyUnsub = db.collection('freshmart')
 .doc('cms_data')
 .onSnapshot(snapshot => {
 const data = snapshot.data();
 if (!data || !data.products || !Array.isArray(data.products)) return;
 // Cek apakah ada produk yang harganya berubah dari snapshot sebelumnya
 if (_legacyPrevProducts) {
 data.products.forEach(newProd => {
 const oldProd = _legacyPrevProducts.find(p => p.id == newProd.id);
 if (oldProd && (oldProd.price !== newProd.price ||
 JSON.stringify(oldProd.variants) !== JSON.stringify(newProd.variants))) {
 // Harga atau varian berubah
 const idx = appData.products.findIndex(p => p.id == newProd.id);
 if (idx > -1) appData.products[idx] = { ...appData.products[idx], ...newProd };
 _debouncedSync(newProd);
 }
 });
 }
 _legacyPrevProducts = data.products;
 }, err => {
 console.warn('[PriceWatcher] cms_data listener error:', err);
 _priceWatcherLegacyUnsub = null;
 });
 }
};

window.stopPriceWatcher = () => {
 if (_priceWatcherUnsub) { _priceWatcherUnsub(); _priceWatcherUnsub = null; }
 if (_priceWatcherLegacyUnsub) { _priceWatcherLegacyUnsub(); _priceWatcherLegacyUnsub = null; }
 clearTimeout(_priceDebounceTimer);
};

